205	#[cfg(all(target_os = "linux", any(feature = "wayland", feature = "x11")))]
206	async fn listen_for_system_wake(wake_sender: Sender<()>) -> anyhow::Result<()> {
207	    use futures::StreamExt as _;
208	
209	    let connection = ashpd::zbus::Connection::system().await?;
210	    let proxy = ashpd::zbus::Proxy::new(
211	        &connection,
212	        "org.freedesktop.login1",
213	        "/org/freedesktop/login1",
214	        "org.freedesktop.login1.Manager",
215	    )
216	    .await?;
217	    let mut sleep_events = proxy.receive_signal("PrepareForSleep").await?;
218	
219	    while let Some(message) = sleep_events.next().await {
220	        let sleeping = message.body().deserialize::<bool>()?;
221	        if !sleeping {
222	            wake_sender.send(()).ok();
223	        }
224	    }
225	
226	    Ok(())
227	}
