288	    fn restart(&self, binary_path: Option<PathBuf>, arguments: Vec<std::ffi::OsString>) {
289	        use std::os::unix::process::CommandExt as _;
290	
291	        // get the process id of the current process
292	        let app_pid = std::process::id().to_string();
293	        // get the path to the executable
294	        let app_path = if let Some(path) = binary_path {
295	            path
296	        } else {
297	            match self.app_path() {
298	                Ok(path) => path,
299	                Err(err) => {
300	                    log::error!("Failed to get app path: {:?}", err);
301	                    return;
302	                }
303	            }
304	        };
305	
306	        log::info!("Restarting process, using app path: {:?}", app_path);
307	
308	        // Script to wait for the current process to exit and then restart the app.
309	        // Pass dynamic values as positional parameters to avoid shell interpolation issues.
310	        let script = r#"
311	            while kill -0 "$0" 2>/dev/null; do
312	                sleep 0.1
313	            done
314	
315	            app_path="$1"
316	            shift
317	            "$app_path" "$@"
318	            "#;
319	
320	        #[allow(
321	            clippy::disallowed_methods,
